{"command": "set -e
mkdir -p /app/polyglot

cat > /tmp/cpp_part <<'EOF'
#include <algorithm>
#include <iostream>
#include <string>

static std::string adddec(const std::string& x, const std::string& y) {
    std::string r;
    int i = static_cast<int>(x.size()) - 1;
    int j = static_cast<int>(y.size()) - 1;
    int carry = 0;
    while (i >= 0 || j >= 0 || carry) {
        int s = carry;
        if (i >= 0) s += x[i--] - '0';
        if (j >= 0) s += y[j--] - '0';
        r.push_back(static_cast<char>('0' + (s % 10)));
        carry = s / 10;
    }
    std::reverse(r.begin(), r.end());
    return r;
}

int main(int argc, char** argv) {
    if (argc < 2) return 0;
    unsigned long long n = 0;
    try {
        n = std::stoull(argv[1]);
    } catch (...) {
        return 0;
    }
    std::string a = "1", b = "1";
    for (unsigned long long i = 0; i < n; ++i) {
        std::string c = adddec(a, b);
        a = b;
        b = c;
    }
    std::cout << a << '\n';
    return 0;
}
EOF

cat > /tmp/rust_part <<'EOF'
fn add(a: &[u8], b: &[u8]) -> Vec<u8> {
    let mut r = Vec::with_capacity(a.len().max(b.len()) + 1);
    let mut i = a.len();
    let mut j = b.len();
    let mut carry = 0u8;
    while i > 0 || j > 0 || carry > 0 {
        let mut s = carry as u16;
        if i > 0 {
            i -= 1;
            s += (a[i] - b'0') as u16;
        }
        if j > 0 {
            j -= 1;
            s += (b[j] - b'0') as u16;
        }
        r.push(b'0' + ((s % 10) as u8));
        carry = (s / 10) as u8;
    }
    r.reverse();
    r
}
fn main() {
    let n: usize = match std::env::args().nth(1) {
        Some(s) => match s.parse() {
            Ok(v) => v,
            Err(_) => return,
        },
        None => return,
    };
    let mut a = vec![b'1'];
    let mut b = vec![b'1'];
    for _ in 0..n {
        let c = add(&a, &b);
        a = b;
        b = c;
    }
    println!("{}", std::str::from_utf8(&a).unwrap());
}
EOF

{
  printf '/*/* */\n'
  cat /tmp/cpp_part
  printf '// */\n'
  awk '{ print "//\\"; print }' /tmp/rust_part
} > /app/polyglot/main.rs

cd /app/polyglot
rustc /app/polyglot/main.rs
g++ -x c++ /app/polyglot/main.rs -o /app/polyglot/cmain

for n in 0 1 2 3 5 10 20 50 100 200; do
  r=$(/app/polyglot/main "$n")
  c=$(/app/polyglot/cmain "$n")
  e=$(python3 - "$n" <<'PY'
import sys
n = int(sys.argv[1])
a = b = 1
for _ in range(n):
    a, b = b, a + b
print(a)
PY
)
  if [ "$r" != "$e" ] || [ "$c" != "$e" ]; then
    echo "MISMATCH n=$n rust=$r cpp=$c expected=$e"
    exit 1
  fi
done
echo "POLYGLOT_OK"
sed -n '1,12p' /app/polyglot/main.rs"}

